import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import BookGrid from '../components/BookGrid';
import { getBooks } from '../api/backend';
import { useAuth } from '../auth/AuthContext';

// สลับลำดับแบบสุ่มบนสำเนา
function shuffle(list) {
  const copy = [...list];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

function Home() {
  const [picks, setPicks] = useState([]);
  const [status, setStatus] = useState('loading');

  useEffect(() => {
    let ignore = false;
    getBooks()
      .then(list => {
        if (!ignore) {
          setPicks(shuffle(list).slice(0, 10));
          setStatus('success');
        }
      })
      .catch(() => { if (!ignore) setStatus('error'); });
    return () => { ignore = true; };
  }, []);

  return (
    <div className="mx-auto max-w-5xl px-4 md:px-6">
      {/* Hero */}
      <section className="py-14 md:py-20">
        <p className="text-sm font-medium text-amber-600">ร้านหนังสือ ออนไลน์</p>
        <h1 className="mt-2 max-w-2xl text-3xl font-semibold tracking-tight text-slate-900 md:text-5xl">
          📚 NangSuKub
          <br />
          <span className="text-2xl font-normal text-slate-600 md:text-3xl">คลัง E-Book คุณภาพ เปิดอ่านได้ทันทีทุกที่ทุกเวลา</span>
        </h1>
        <p className="mt-4 max-w-xl text-slate-600">
          รวม E-Book ยอดนิยมทั้งไทยและต่างประเทศ สั่งซื้อง่าย รับไฟล์เข้าบัญชีทันที
          ทดลองอ่านตัวอย่างฟรี ค้นหา อ่านรีวิว และเพิ่มในรายการอยากอ่านได้เลย
        </p>
        <div className="mt-6 flex flex-wrap gap-3">
          <Link to="/books" className="rounded-lg bg-amber-500 px-4 py-2 text-sm font-medium text-white hover:bg-amber-600">
            เลือกดู E-Book ทั้งหมด
          </Link>
          <Link to="/register" className="rounded-lg border border-amber-200 bg-white px-4 py-2 text-sm text-amber-700 hover:bg-amber-50">
            สมัครสมาชิก
          </Link>
        </div>
      </section>

      {/* หนังสือแนะนำ */}
      <section className="mb-16">
        <div className="mb-4 flex items-end justify-between">
          <div>
            <h2 className="text-xl font-semibold text-slate-900">หนังสือแนะนำ</h2>
            <p className="text-sm text-slate-500">สุ่มลำดับใหม่ทุกครั้งที่เปิดหน้า</p>
          </div>
          <button onClick={() => setPicks(p => shuffle(p))} className="text-sm text-amber-600 hover:underline">
            สุ่มใหม่
          </button>
        </div>
        <BookGrid books={picks} status={status} />
      </section>
    </div>
  );
}

export default Home;
